window.LESSON_DATA = {"schemaVersion":"1.0.0","version":"1.0.1","buildDate":"2026-07-29","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":1,"title":"Number and Algebra"},"lesson":{"number":"1.7","slug":"loans-annuities","title":"Loans, Annuities and Amortization","subtitle":"Use financial technology to model regular payments, outstanding balances and long-term consequences.","syllabus_focus":"SL 1.7 — Amortization and annuities using technology; interpretation of financial results.","skill_keys":["IBAI.U1.SEQUENCES","IBAI.U1.MODELING"],"objectives":["Interpret finance-solver variables and cash-flow signs.","Calculate loan payments and total interest.","Model annuity savings and outstanding balances.","Compare repayment strategies and evaluate assumptions."],"vocab":["loan","amortization","annuity","present value","future value","payment","periodic rate","term","outstanding balance","total interest"],"technology":"Use a finance solver and a spreadsheet amortization table. Reconcile both methods and inspect the balance after selected payments.","transition":"Financial-technology modelling remains aligned with the applications-and-interpretation philosophy; confirm detailed 2029 guide wording before reuse."},"slides":[{"section":"Launch","title":"1.7 · Loans, Annuities and Amortization","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB DP Mathematics · Applications and Interpretation SL</div><h1><span class=\"cover-number\">1.7</span>Loans, Annuities and Amortization</h1><p class=\"cover-subtitle\">Use financial technology to model regular payments, outstanding balances and long-term consequences.</p><div class=\"pill-row\"><span>Current syllabus</span><span>Technology-rich</span><span>Modelling</span><span>Original practice</span></div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Changing interest and principal shares\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"26\" y=\"31\" fill=\"#17324D\" font-weight=\"800\">Payment composition over time</text><g><rect x=\"45\" y=\"55\" width=\"42\" height=\"85\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"45\" y=\"55\" width=\"42\" height=\"0\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"107\" y=\"60\" width=\"42\" height=\"80\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"107\" y=\"55\" width=\"42\" height=\"5\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"169\" y=\"65\" width=\"42\" height=\"75\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"169\" y=\"55\" width=\"42\" height=\"10\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"231\" y=\"70\" width=\"42\" height=\"70\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"231\" y=\"55\" width=\"42\" height=\"15\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"293\" y=\"75\" width=\"42\" height=\"65\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"293\" y=\"55\" width=\"42\" height=\"20\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"355\" y=\"80\" width=\"42\" height=\"60\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"355\" y=\"55\" width=\"42\" height=\"25\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"417\" y=\"85\" width=\"42\" height=\"55\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"417\" y=\"55\" width=\"42\" height=\"30\" fill=\"#177E89\" opacity=\".95\"/></g><text x=\"55\" y=\"162\" fill=\"#7A1733\">interest share falls</text><text x=\"315\" y=\"162\" fill=\"#177E89\">principal share rises</text></svg></div>","kind":"cover","eyebrow":"Unit 1 · Number and Algebra"},{"section":"Launch","title":"Your place in Unit 1","html":"<div class=\"unit-map\"><div class=\"map-node \"><b>1.1</b><span>Scientific Notation and Orders of Magnitude</span></div><div class=\"map-node \"><b>1.2</b><span>Arithmetic Sequences and Series</span></div><div class=\"map-node \"><b>1.3</b><span>Geometric Sequences and Series</span></div><div class=\"map-node \"><b>1.4</b><span>Financial Applications of Sequences</span></div><div class=\"map-node \"><b>1.5</b><span>Introduction to Logarithms</span></div><div class=\"map-node \"><b>1.6</b><span>Approximation, Bounds and Percentage Error</span></div><div class=\"map-node active\"><b>1.7</b><span>Loans, Annuities and Amortization</span></div><div class=\"map-node \"><b>1.8</b><span>Technology for Equations and Systems</span></div></div><p class=\"callout\">The course moves from representation and discrete change to financial modelling, uncertainty and technology-based solution methods.</p>","kind":"content","eyebrow":""},{"section":"Launch","title":"Syllabus focus","html":"<div class=\"focus-card\"><h3>Current course alignment</h3><p>SL 1.7 — Amortization and annuities using technology; interpretation of financial results.</p><p><b>Platform mastery keys:</b> IBAI.U1.SEQUENCES, IBAI.U1.MODELING</p></div><div class=\"transition-note\">Financial-technology modelling remains aligned with the applications-and-interpretation philosophy; confirm detailed 2029 guide wording before reuse.</div>","kind":"content","eyebrow":""},{"section":"Inquiry","title":"A question worth investigating","html":"<blockquote>How does the timing of equal payments affect what a loan or savings plan becomes?</blockquote><p>Record an initial response. Return to it at the end and identify how your reasoning changed.</p><textarea class=\"student-note\" data-note=\"inquiry\" aria-label=\"Inquiry response\"></textarea>","kind":"inquiry","eyebrow":""},{"section":"Inquiry","title":"Learning intentions","html":"<div class=\"two-col\"><div><h3>By the end, you can…</h3><ul class=\"check-list\"><li>Interpret finance-solver variables and cash-flow signs.</li><li>Calculate loan payments and total interest.</li><li>Model annuity savings and outstanding balances.</li><li>Compare repayment strategies and evaluate assumptions.</li></ul></div><div><h3>Evidence of understanding</h3><ul class=\"check-list\"><li>Choose an efficient representation.</li><li>Use technology transparently.</li><li>Interpret rather than merely calculate.</li><li>Evaluate assumptions and precision.</li></ul></div></div>","kind":"content","eyebrow":""},{"section":"Diagnostic","title":"Prior-knowledge diagnostic","html":"<div class=\"student-turn\"><h3>Try before instruction</h3><p>Why does repaying QAR 100,000 over ten years cost more than QAR 100,000 in total?</p><textarea class=\"student-note\" data-note=\"diagnostic\"></textarea><details><summary>Diagnostic lens</summary><p>Focus on structure, units and the meaning of the result—not just a final number.</p></details></div>","kind":"student","eyebrow":""},{"section":"Language","title":"Core vocabulary","html":"<div class=\"vocab-grid\"><div class=\"vocab-chip\">loan</div><div class=\"vocab-chip\">amortization</div><div class=\"vocab-chip\">annuity</div><div class=\"vocab-chip\">present value</div><div class=\"vocab-chip\">future value</div><div class=\"vocab-chip\">payment</div><div class=\"vocab-chip\">periodic rate</div><div class=\"vocab-chip\">term</div><div class=\"vocab-chip\">outstanding balance</div><div class=\"vocab-chip\">total interest</div></div><p class=\"callout\">Use precise vocabulary in every explanation. In IB mathematics, communication earns meaning, not decoration.</p>","kind":"content","eyebrow":""},{"section":"Approach","title":"The AI modelling cycle","html":"<div class=\"cycle\"><div>Context</div><span>→</span><div>Assumptions</div><span>→</span><div>Mathematical form</div><span>→</span><div>Technology & computation</div><span>→</span><div>Interpretation</div><span>→</span><div>Validation & refinement</div></div><p>Every substantial task in this lesson returns to this cycle. A numerical answer without interpretation is unfinished.</p>","kind":"content","eyebrow":""},{"section":"Concept 1","title":"Cash-flow conventions","html":"<div class=\"concept-grid\"><div><p>Finance solvers distinguish money received from money paid. A consistent sign convention prevents impossible-looking outputs.</p><div class=\"formula-panel\">\\[PV,\\ FV,\\ PMT\\text{ use opposite signs for opposite cash-flow directions}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Changing interest and principal shares\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"26\" y=\"31\" fill=\"#17324D\" font-weight=\"800\">Payment composition over time</text><g><rect x=\"45\" y=\"55\" width=\"42\" height=\"85\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"45\" y=\"55\" width=\"42\" height=\"0\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"107\" y=\"60\" width=\"42\" height=\"80\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"107\" y=\"55\" width=\"42\" height=\"5\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"169\" y=\"65\" width=\"42\" height=\"75\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"169\" y=\"55\" width=\"42\" height=\"10\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"231\" y=\"70\" width=\"42\" height=\"70\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"231\" y=\"55\" width=\"42\" height=\"15\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"293\" y=\"75\" width=\"42\" height=\"65\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"293\" y=\"55\" width=\"42\" height=\"20\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"355\" y=\"80\" width=\"42\" height=\"60\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"355\" y=\"55\" width=\"42\" height=\"25\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"417\" y=\"85\" width=\"42\" height=\"55\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"417\" y=\"55\" width=\"42\" height=\"30\" fill=\"#177E89\" opacity=\".95\"/></g><text x=\"55\" y=\"162\" fill=\"#7A1733\">interest share falls</text><text x=\"315\" y=\"162\" fill=\"#177E89\">principal share rises</text></svg></div>","kind":"content","eyebrow":"Concept cycle 1 of 5"},{"section":"Concept 1","title":"Worked example · Cash-flow conventions","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>For a borrower receiving QAR 80,000 and making monthly payments, choose signs.</p></div><div class=\"method\"><span>Reasoning</span><p>One convention is \\(PV=+80000\\), \\(PMT<0\\), and final \\(FV=0\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 1","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>For monthly deposits into savings, what signs could be used for \\(PMT\\) and \\(FV\\)?</p><textarea class=\"student-note\" data-note=\"turn-1\"></textarea><details><summary>Reveal answer and check</summary><p>Deposits may be negative cash flow and the final accumulated value positive.</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 1","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>Deposits may be negative cash flow and the final accumulated value positive.</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>A negative payment is usually a direction convention, not a negative-sized payment.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 2","title":"Level-payment loans","html":"<div class=\"concept-grid\"><div><p>Each payment covers current interest and reduces principal. Early payments contain more interest because the balance is larger.</p><div class=\"formula-panel\">\\[PMT=PV\\frac{i}{1-(1+i)^{-n}}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Changing interest and principal shares\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"26\" y=\"31\" fill=\"#17324D\" font-weight=\"800\">Payment composition over time</text><g><rect x=\"45\" y=\"55\" width=\"42\" height=\"85\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"45\" y=\"55\" width=\"42\" height=\"0\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"107\" y=\"60\" width=\"42\" height=\"80\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"107\" y=\"55\" width=\"42\" height=\"5\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"169\" y=\"65\" width=\"42\" height=\"75\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"169\" y=\"55\" width=\"42\" height=\"10\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"231\" y=\"70\" width=\"42\" height=\"70\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"231\" y=\"55\" width=\"42\" height=\"15\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"293\" y=\"75\" width=\"42\" height=\"65\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"293\" y=\"55\" width=\"42\" height=\"20\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"355\" y=\"80\" width=\"42\" height=\"60\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"355\" y=\"55\" width=\"42\" height=\"25\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"417\" y=\"85\" width=\"42\" height=\"55\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"417\" y=\"55\" width=\"42\" height=\"30\" fill=\"#177E89\" opacity=\".95\"/></g><text x=\"55\" y=\"162\" fill=\"#7A1733\">interest share falls</text><text x=\"315\" y=\"162\" fill=\"#177E89\">principal share rises</text></svg></div>","kind":"content","eyebrow":"Concept cycle 2 of 5"},{"section":"Concept 2","title":"Worked example · Level-payment loans","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Find the monthly payment on QAR 60,000 at 5.4% nominal annual interest for 5 years.</p></div><div class=\"method\"><span>Reasoning</span><p>With \\(i=0.054/12,n=60\\), \\(PMT\\approx\\) QAR 1143.79.</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 2","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>State the finance-solver inputs for QAR 120,000 at 4.8% over 8 years, monthly.</p><textarea class=\"student-note\" data-note=\"turn-2\"></textarea><details><summary>Reveal answer and check</summary><p>\\(N=96\\), \\(I\\%=4.8\\), \\(PV=120000\\), \\(FV=0\\), \\(P/Y=C/Y=12\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 2","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(N=96\\), \\(I\\%=4.8\\), \\(PV=120000\\), \\(FV=0\\), \\(P/Y=C/Y=12\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>The annual percentage rate is not the monthly periodic rate.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 3","title":"Total interest and amortization","html":"<div class=\"concept-grid\"><div><p>Total paid is payment times number of payments, adjusted for any fees or final rounding. Total interest is total paid minus principal.</p><div class=\"formula-panel\">\\[I_{\\text{total}}=n(PMT)-PV\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Changing interest and principal shares\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"26\" y=\"31\" fill=\"#17324D\" font-weight=\"800\">Payment composition over time</text><g><rect x=\"45\" y=\"55\" width=\"42\" height=\"85\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"45\" y=\"55\" width=\"42\" height=\"0\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"107\" y=\"60\" width=\"42\" height=\"80\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"107\" y=\"55\" width=\"42\" height=\"5\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"169\" y=\"65\" width=\"42\" height=\"75\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"169\" y=\"55\" width=\"42\" height=\"10\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"231\" y=\"70\" width=\"42\" height=\"70\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"231\" y=\"55\" width=\"42\" height=\"15\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"293\" y=\"75\" width=\"42\" height=\"65\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"293\" y=\"55\" width=\"42\" height=\"20\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"355\" y=\"80\" width=\"42\" height=\"60\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"355\" y=\"55\" width=\"42\" height=\"25\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"417\" y=\"85\" width=\"42\" height=\"55\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"417\" y=\"55\" width=\"42\" height=\"30\" fill=\"#177E89\" opacity=\".95\"/></g><text x=\"55\" y=\"162\" fill=\"#7A1733\">interest share falls</text><text x=\"315\" y=\"162\" fill=\"#177E89\">principal share rises</text></svg></div>","kind":"content","eyebrow":"Concept cycle 3 of 5"},{"section":"Concept 3","title":"Worked example · Total interest and amortization","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>For a QAR 60,000 loan with monthly payment QAR 1143.79 for 60 months, estimate total interest.</p></div><div class=\"method\"><span>Reasoning</span><p>\\(60(1143.79)-60000\\approx\\) QAR 8627.40.</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 3","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Why may the last payment differ slightly from the others?</p><textarea class=\"student-note\" data-note=\"turn-3\"></textarea><details><summary>Reveal answer and check</summary><p>Currency rounding each period can leave a small residual balance.</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 3","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>Currency rounding each period can leave a small residual balance.</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Interest is not simply principal × annual rate × years for an amortized compound-interest loan.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 4","title":"Annuity savings","html":"<div class=\"concept-grid\"><div><p>A regular end-of-period deposit forms an ordinary annuity. Earlier deposits earn interest for longer.</p><div class=\"formula-panel\">\\[FV=PMT\\frac{(1+i)^n-1}{i}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Changing interest and principal shares\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"26\" y=\"31\" fill=\"#17324D\" font-weight=\"800\">Payment composition over time</text><g><rect x=\"45\" y=\"55\" width=\"42\" height=\"85\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"45\" y=\"55\" width=\"42\" height=\"0\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"107\" y=\"60\" width=\"42\" height=\"80\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"107\" y=\"55\" width=\"42\" height=\"5\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"169\" y=\"65\" width=\"42\" height=\"75\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"169\" y=\"55\" width=\"42\" height=\"10\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"231\" y=\"70\" width=\"42\" height=\"70\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"231\" y=\"55\" width=\"42\" height=\"15\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"293\" y=\"75\" width=\"42\" height=\"65\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"293\" y=\"55\" width=\"42\" height=\"20\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"355\" y=\"80\" width=\"42\" height=\"60\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"355\" y=\"55\" width=\"42\" height=\"25\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"417\" y=\"85\" width=\"42\" height=\"55\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"417\" y=\"55\" width=\"42\" height=\"30\" fill=\"#177E89\" opacity=\".95\"/></g><text x=\"55\" y=\"162\" fill=\"#7A1733\">interest share falls</text><text x=\"315\" y=\"162\" fill=\"#177E89\">principal share rises</text></svg></div>","kind":"content","eyebrow":"Concept cycle 4 of 5"},{"section":"Concept 4","title":"Worked example · Annuity savings","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Deposit QAR 500 monthly for 6 years at 4.2% nominal compounded monthly.</p></div><div class=\"method\"><span>Reasoning</span><p>\\(FV\\approx\\) QAR 40,830.24.</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 4","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>How would making deposits at the beginning of each month change the result?</p><textarea class=\"student-note\" data-note=\"turn-4\"></textarea><details><summary>Reveal answer and check</summary><p>Multiply the ordinary-annuity future value by \\(1+i\\); each deposit earns one extra period.</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 4","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>Multiply the ordinary-annuity future value by \\(1+i\\); each deposit earns one extra period.</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Monthly deposits are not equivalent to one annual deposit of the same total because timing matters.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 5","title":"Comparing repayment strategies","html":"<div class=\"concept-grid\"><div><p>Extra payments reduce principal earlier and can save substantial interest. A fair comparison includes affordability, fees and opportunity cost.</p><div class=\"formula-panel\">\\[B_k=PV(1+i)^k-PMT\\frac{(1+i)^k-1}{i}\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Changing interest and principal shares\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"26\" y=\"31\" fill=\"#17324D\" font-weight=\"800\">Payment composition over time</text><g><rect x=\"45\" y=\"55\" width=\"42\" height=\"85\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"45\" y=\"55\" width=\"42\" height=\"0\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"107\" y=\"60\" width=\"42\" height=\"80\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"107\" y=\"55\" width=\"42\" height=\"5\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"169\" y=\"65\" width=\"42\" height=\"75\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"169\" y=\"55\" width=\"42\" height=\"10\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"231\" y=\"70\" width=\"42\" height=\"70\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"231\" y=\"55\" width=\"42\" height=\"15\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"293\" y=\"75\" width=\"42\" height=\"65\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"293\" y=\"55\" width=\"42\" height=\"20\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"355\" y=\"80\" width=\"42\" height=\"60\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"355\" y=\"55\" width=\"42\" height=\"25\" fill=\"#177E89\" opacity=\".95\"/></g><g><rect x=\"417\" y=\"85\" width=\"42\" height=\"55\" fill=\"#7A1733\" opacity=\".85\"/><rect x=\"417\" y=\"55\" width=\"42\" height=\"30\" fill=\"#177E89\" opacity=\".95\"/></g><text x=\"55\" y=\"162\" fill=\"#7A1733\">interest share falls</text><text x=\"315\" y=\"162\" fill=\"#177E89\">principal share rises</text></svg></div>","kind":"content","eyebrow":"Concept cycle 5 of 5"},{"section":"Concept 5","title":"Worked example · Comparing repayment strategies","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Explain why an extra QAR 200 paid early usually saves more interest than the same extra amount paid near the end.</p></div><div class=\"method\"><span>Reasoning</span><p>It reduces the balance on which interest is calculated for more future periods.</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 5","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Name two outputs to compare when choosing loan terms.</p><textarea class=\"student-note\" data-note=\"turn-5\"></textarea><details><summary>Reveal answer and check</summary><p>Monthly payment, total interest, total paid, term length and remaining balance are all relevant.</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 5","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>Monthly payment, total interest, total paid, term length and remaining balance are all relevant.</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>The lowest monthly payment can correspond to the highest total cost.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Technology","title":"Interactive exploration","html":"<div id=\"lesson-lab\" class=\"lab\" data-lab=\"1.7\"></div><p class=\"lab-note\">Change more than one input. Predict before pressing calculate, then explain what stays invariant.</p>","kind":"lab","eyebrow":""},{"section":"Technology","title":"Transparent technology workflow","html":"<div class=\"workflow\"><div><b>1</b> Define variables and domain</div><div><b>2</b> Enter the mathematical model</div><div><b>3</b> Choose an appropriate tool</div><div><b>4</b> Record settings/output</div><div><b>5</b> Verify independently</div><div><b>6</b> Interpret and round</div></div><p>Use a finance solver and a spreadsheet amortization table. Reconcile both methods and inspect the balance after selected payments.</p>","kind":"content","eyebrow":""},{"section":"Application","title":"Global and local context","html":"<div class=\"context-card\"><span>Context challenge</span><p>Model a realistic education, vehicle or equipment financing decision in QAR. Compare at least two terms and one extra-payment scenario.</p></div><textarea class=\"student-note tall\" data-note=\"context\"></textarea>","kind":"student","eyebrow":""},{"section":"Inquiry","title":"Mini-investigation","html":"<div class=\"investigation\"><h3>Question → evidence → conclusion</h3><p>Construct an amortization table, visualize principal versus interest portions, and explain how one policy change affects affordability and total cost.</p><ul class=\"check-list\"><li>State the question and variables.</li><li>Record assumptions and data sources.</li><li>Show mathematics and technology output.</li><li>Interpret, evaluate and refine.</li></ul></div>","kind":"investigation","eyebrow":""},{"section":"Assessment","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Write down</b><span>Give the result with little or no working.</span></div><div><b>Calculate</b><span>Show enough method for the result to be reproducible.</span></div><div><b>Determine</b><span>Reach a result with supporting reasoning.</span></div><div><b>Explain</b><span>Give causes, mechanisms or mathematical meaning.</span></div><div><b>Interpret</b><span>Translate mathematics back into context.</span></div><div><b>Comment</b><span>Make a judgement supported by evidence.</span></div></div>","kind":"content","eyebrow":""},{"section":"Assessment","title":"Vehicle loan","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 1-style short response</span><span>10 marks</span><span>Finance solver / GDC expected</span></div><h3>Vehicle loan</h3><p>A QAR 85,000 loan has a nominal annual rate of 5.2%, compounded monthly, and a 6-year term.</p><div class=\"task-part\"><b>(a)</b> State \\(N\\), the periodic rate, \\(PV\\) and \\(FV\\) for a finance solver. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(b)</b> Find the monthly payment. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(c)</b> Find the total interest paid. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(d)</b> Find the outstanding balance after 24 payments. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(e)</b> Explain why the interest part of a payment decreases over time. <span class=\"marks\">[1]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Vehicle loan · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Vehicle loan — worked markscheme</h3><div class=\"solution-part\"><b>(a) \\(N=72\\), monthly rate \\(0.052/12\\), \\(PV=85000\\), \\(FV=0\\) with consistent signs.</b><p>A1 periods; A1 periodic rate; A1 present/future values and signs.</p></div><div class=\"solution-part\"><b>(b) QAR 1,376.82</b><p>M1 correct finance setup; A1 payment.</p></div><div class=\"solution-part\"><b>(c) QAR 14,130.96</b><p>M1 total payments minus principal; A1 value.</p></div><div class=\"solution-part\"><b>(d) QAR 59,550.98</b><p>M1 balance method/solver; A1 value.</p></div><div class=\"solution-part\"><b>(e) Interest is calculated on a declining outstanding balance.</b><p>A1 correct explanation.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Assessment","title":"University savings plan","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 2-style extended response</span><span>12 marks</span><span>Finance solver / spreadsheet expected</span></div><h3>University savings plan</h3><p>A family deposits QAR 900 at the end of each month into an account earning 4.8% nominal annual interest compounded monthly for 8 years.</p><div class=\"task-part\"><b>(a)</b> Find the future value. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(b)</b> Find total contributions and interest earned. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(c)</b> Find the future value if deposits are made at the beginning of each month. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(d)</b> The target is QAR 110,000. Find the end-of-month deposit required. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(e)</b> Give one limitation of assuming a constant interest rate. <span class=\"marks\">[1]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"University savings plan · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>University savings plan — worked markscheme</h3><div class=\"solution-part\"><b>(a) QAR 105,079.80</b><p>M1 periodic rate/periods; M1 annuity calculation; A1 value.</p></div><div class=\"solution-part\"><b>(b) Contributions QAR 86,400.00; interest QAR 18,679.80</b><p>A1 contributions; M1 subtraction; A1 interest.</p></div><div class=\"solution-part\"><b>(c) QAR 105,500.12</b><p>M1 annuity-due adjustment; A1 value.</p></div><div class=\"solution-part\"><b>(d) QAR 942.14</b><p>M1 rearranges annuity relation; M1 substitutes; A1 payment.</p></div><div class=\"solution-part\"><b>(e) Market rates and account terms can change.</b><p>A1 relevant limitation.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Connections","title":"Where this mathematics connects","html":"<div class=\"connection-grid\"><div>Geometric series</div><div>Exponential decay of balance</div><div>Personal finance</div><div>Spreadsheet modelling</div></div><p>Write one sentence describing a connection you did not see at the start.</p><textarea class=\"student-note\" data-note=\"connection\"></textarea>","kind":"content","eyebrow":""},{"section":"Synthesis","title":"Five ideas to retain","html":"<ul class=\"check-list\"><li>Cash-flow conventions: Finance solvers distinguish money received from money paid.</li><li>Level-payment loans: Each payment covers current interest and reduces principal.</li><li>Total interest and amortization: Total paid is payment times number of payments, adjusted for any fees or final rounding.</li><li>Annuity savings: A regular end-of-period deposit forms an ordinary annuity.</li><li>Comparing repayment strategies: Extra payments reduce principal earlier and can save substantial interest.</li></ul>","kind":"summary","eyebrow":""},{"section":"Reflection","title":"Return to the inquiry question","html":"<blockquote>How does the timing of equal payments affect what a loan or savings plan becomes?</blockquote><textarea class=\"student-note tall\" data-note=\"reflection\"></textarea><div class=\"reflection-grid\"><label><input type=\"checkbox\" data-reflect=\"model\"> I can model</label><label><input type=\"checkbox\" data-reflect=\"calculate\"> I can calculate</label><label><input type=\"checkbox\" data-reflect=\"interpret\"> I can interpret</label><label><input type=\"checkbox\" data-reflect=\"evaluate\"> I can evaluate</label></div>","kind":"reflection","eyebrow":""},{"section":"Exit","title":"Exit ticket","html":"<div class=\"exit-grid\"><div><b>One calculation</b><p>Create and solve a new example using today’s central formula.</p></div><div><b>One explanation</b><p>Describe a common error and how to detect it.</p></div><div><b>One evaluation</b><p>State one assumption that could change a conclusion.</p></div></div><textarea class=\"student-note tall\" data-note=\"exit\"></textarea>","kind":"student","eyebrow":""},{"section":"Next","title":"Practice Studio","html":"<div class=\"launch-panel\"><h2>40 original questions</h2><p>Four levels: Foundation, Application, Reasoning and Challenge. Every item includes marks, calculator guidance, hints and a complete solution.</p><button class=\"route-jump\" data-go=\"practice\">Open Practice Studio</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Independent timed quiz","html":"<div class=\"launch-panel\"><h2>10 fresh questions</h2><p>Complete the quiz under a suggested 25-minute timer, then review explanations and update your mastery reflection.</p><button class=\"route-jump\" data-go=\"quiz\">Start timed quiz</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Authenticated question-bank bridge","html":"<div class=\"bank-bridge\"><h2>More practice on the platform</h2><p>This lesson maps to <code>IBAI.U1.SEQUENCES, IBAI.U1.MODELING</code>. The attached private banks stay inside authenticated school access; no private prompt is copied into this public lesson file.</p><a href=\"https://2ed944-cloud.github.io/ECHS-Math/question-bank/practice.html?course=ib-math-ai&unit=1&lesson=1.7\" class=\"button-link\">Open additional bank practice</a></div>","kind":"launch","eyebrow":""}],"practice":[{"id":"IBAI-1.7-P01","level":"Foundation","prompt":"Find the monthly payment on QAR 60,000 at 5.4% nominal annual interest for 5 years.","answer":"\\(1,143.30\\)","solution":"Use \\(i=0.054/12\\), \\(n=60\\), and \\(PMT=PV\\,i/[1-(1+i)^{-n}]\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":1143.302369487256,"tolerance":0.011}},{"id":"IBAI-1.7-P02","level":"Foundation","prompt":"Find the monthly payment on QAR 120,000 at 4.8% for 8 years.","answer":"\\(1,507.79\\)","solution":"Use 96 monthly payments and periodic rate 0.048/12.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":1507.790305771134,"tolerance":0.011}},{"id":"IBAI-1.7-P03","level":"Foundation","prompt":"Find the quarterly payment on QAR 40,000 at 6% nominal compounded quarterly for 4 years.","answer":"\\(2,830.60\\)","solution":"Use \\(i=0.06/4\\) and \\(n=16\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":2830.603113187999,"tolerance":0.011}},{"id":"IBAI-1.7-P04","level":"Foundation","prompt":"A zero-interest QAR 18,000 loan is repaid monthly over 3 years. Find the payment.","answer":"\\(500.00\\)","solution":"Divide principal by 36 equal payments.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":500.0,"tolerance":1e-06}},{"id":"IBAI-1.7-P05","level":"Foundation","prompt":"Find the future value of QAR 500 deposited monthly for 6 years at 4.2% nominal compounded monthly.","answer":"\\(40,861.44\\)","solution":"Use ordinary-annuity future value with \\(i=0.042/12\\), \\(n=72\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":40861.44191193073,"tolerance":0.011}},{"id":"IBAI-1.7-P06","level":"Foundation","prompt":"Find the future value of QAR 350 deposited monthly for 4 years at 3.6%.","answer":"\\(18,040.77\\)","solution":"Use \\(i=0.036/12\\), \\(n=48\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":18040.770787588997,"tolerance":0.011}},{"id":"IBAI-1.7-P07","level":"Foundation","prompt":"A monthly payment is QAR 900 for 60 months on a QAR 45,000 loan. Ignoring fees, find total interest.","answer":"\\(9,000.00\\)","solution":"Total paid minus principal.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":9000,"tolerance":1e-06}},{"id":"IBAI-1.7-P08","level":"Foundation","prompt":"A QAR 80,000 loan is repaid by QAR 1550 monthly for 60 months. Find total paid.","answer":"\\(93,000.00\\)","solution":"Multiply payment by number of payments.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":93000,"tolerance":1e-06}},{"id":"IBAI-1.7-P09","level":"Foundation","prompt":"For a 7-year loan with monthly payments, find the number of payments.","answer":"\\(84.00\\)","solution":"\\(7\\times12=84\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":84,"tolerance":1e-06}},{"id":"IBAI-1.7-P10","level":"Foundation","prompt":"For 5.4% nominal annual interest compounded monthly, find the periodic monthly rate as a decimal.","answer":"\\(0.0045\\)","solution":"Divide nominal annual rate by 12.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["finance solver"],"check":{"mode":"number","value":0.0045,"tolerance":5e-05}},{"id":"IBAI-1.7-P11","level":"Application","prompt":"Find the total interest on QAR 60,000 at 5.4% for 5 years using level monthly payments.","answer":"\\(8,598.14\\)","solution":"Calculate the payment with full precision, multiply by 60, then subtract principal.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":8598.142169235362,"tolerance":0.011}},{"id":"IBAI-1.7-P12","level":"Application","prompt":"A QAR 60,000 loan at 5.4% nominal annual interest is repaid monthly over 5 years. Find the outstanding balance after 24 payments.","answer":"\\(37,919.45\\)","solution":"Use the remaining-balance formula or finance solver with 36 payments remaining.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":37919.44736434438,"tolerance":0.011}},{"id":"IBAI-1.7-P13","level":"Application","prompt":"Find the outstanding balance after 36 payments on QAR 120,000 at 4.8% over 8 years.","answer":"\\(80,288.13\\)","solution":"Use the original payment and accumulate 36 periods.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":80288.12669231585,"tolerance":0.011}},{"id":"IBAI-1.7-P14","level":"Application","prompt":"QAR 700 is deposited monthly for 5 years at 5% nominal compounded monthly. Find the future value.","answer":"\\(47,604.26\\)","solution":"Ordinary annuity with 60 end-of-month deposits.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":47604.25798858999,"tolerance":0.011}},{"id":"IBAI-1.7-P15","level":"Application","prompt":"QAR 700 is deposited at the end of each month for 5 years. Find the total contributions.","answer":"\\(42,000.00\\)","solution":"Multiply deposit by number of deposits.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":42000,"tolerance":1e-06}},{"id":"IBAI-1.7-P16","level":"Application","prompt":"QAR 700 is deposited monthly for 5 years at 5% nominal annual interest compounded monthly. The future value is QAR 47,604.25798859. Find the interest earned.","answer":"\\(5,604.26\\)","solution":"Future value minus total contributions.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":5604.25798858999,"tolerance":0.011}},{"id":"IBAI-1.7-P17","level":"Application","prompt":"A QAR 90,000 loan at 6.2% is repaid monthly over 6 years. Find the payment.","answer":"\\(1,500.07\\)","solution":"Use \\(i=0.062/12\\), \\(n=72\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":1500.0713993084896,"tolerance":0.011}},{"id":"IBAI-1.7-P18","level":"Application","prompt":"A QAR 90,000 loan charges 6.2% nominal annual interest compounded monthly. If QAR 1700 is paid monthly, find the balance after 36 payments.","answer":"\\(41,274.31\\)","solution":"Accumulate the loan and subtract accumulated payments.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":41274.31177549358,"tolerance":0.011}},{"id":"IBAI-1.7-P19","level":"Application","prompt":"Find the future value of beginning-of-month deposits of QAR 400 for 3 years at 4.8% nominal monthly.","answer":"\\(15,517.06\\)","solution":"An annuity due equals ordinary-annuity value multiplied by one extra-period factor.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":15517.06435720875,"tolerance":0.011}},{"id":"IBAI-1.7-P20","level":"Application","prompt":"A QAR 50,000 loan at 5% is repaid quarterly over 5 years. Find total interest.","answer":"\\(6,820.39\\)","solution":"Find the 20 quarterly payments and subtract principal from total paid.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["loan","annuity"],"check":{"mode":"number","value":6820.389631804574,"tolerance":0.011}},{"id":"IBAI-1.7-P21","level":"Reasoning","prompt":"For the QAR 60,000, 5.4%, 5-year loan, find the interest portion of the first monthly payment.","answer":"\\(270.00\\)","solution":"First-period interest equals opening balance × monthly rate.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":270.0,"tolerance":1e-06}},{"id":"IBAI-1.7-P22","level":"Reasoning","prompt":"For a QAR 60,000 loan at 5.4% nominal annual interest over 5 years, the monthly payment is QAR 1143.302369. Find the principal portion of the first payment.","answer":"\\(873.30\\)","solution":"Payment minus first-period interest.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":873.3023694872561,"tolerance":0.011}},{"id":"IBAI-1.7-P23","level":"Reasoning","prompt":"Compare a QAR 100,000 loan at 5% over 5 years and 8 years. Find the 5-year monthly payment minus the 8-year payment.","answer":"\\(621.13\\)","solution":"Longer term lowers the payment; compute both consistently.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":621.131363188716,"tolerance":0.011}},{"id":"IBAI-1.7-P24","level":"Reasoning","prompt":"Compare QAR 100,000 loans at 5% nominal annual interest with monthly payments over 5 years and 8 years. Find total interest for the 8-year term minus total interest for the 5-year term.","answer":"\\(8,307.83\\)","solution":"The longer term generally costs more total interest.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":8307.830252322849,"tolerance":0.011}},{"id":"IBAI-1.7-P25","level":"Reasoning","prompt":"A borrower adds QAR 200 to the required monthly payment on QAR 75,000 at 5.5% over 7 years. Find the balance after 36 payments.","answer":"\\(38,533.40\\)","solution":"Use the larger payment in the balance formula.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":38533.40353534452,"tolerance":0.011}},{"id":"IBAI-1.7-P26","level":"Reasoning","prompt":"A saver deposits QAR 600 monthly for 8 years at 4%. Find interest as a percentage of total contributions.","answer":"\\(17.62\\)","solution":"Compare growth earned with contributions.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":17.623474760351275,"tolerance":0.011}},{"id":"IBAI-1.7-P27","level":"Reasoning","prompt":"A finance solver shows PMT = −1450 when PV = +80,000. Enter the payment magnitude.","answer":"\\(1,450.00\\)","solution":"The negative sign indicates cash-flow direction; magnitude is QAR 1450.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":1450,"tolerance":1e-06}},{"id":"IBAI-1.7-P28","level":"Reasoning","prompt":"A QAR 30,000 loan has payment QAR 580 monthly at 4.5%. Find the balance after 12 payments.","answer":"\\(24,272.84\\)","solution":"Use the actual payment rather than a formula-derived one.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":24272.835144939832,"tolerance":0.011}},{"id":"IBAI-1.7-P29","level":"Reasoning","prompt":"A saver wants QAR 100,000 in 10 years at 5% nominal monthly. Find the required end-of-month deposit.","answer":"\\(643.99\\)","solution":"Rearrange the annuity future-value formula for PMT.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":643.9884857240887,"tolerance":0.011}},{"id":"IBAI-1.7-P30","level":"Reasoning","prompt":"A loan payment of QAR 1143.786 is recorded as QAR 1143.79. Find the absolute rounding difference per payment.","answer":"\\(0.004\\)","solution":"Subtract the unrounded value from the displayed currency payment.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["amortization reasoning"],"check":{"mode":"number","value":0.0039999999999054126,"tolerance":0.0009999999999763531}},{"id":"IBAI-1.7-P31","level":"Challenge","prompt":"A QAR 150,000 loan at 5.2% is repaid monthly over 10 years. After 36 payments, QAR 20,000 is paid immediately. Find the new balance.","answer":"\\(92,853.40\\)","solution":"Find the balance immediately after payment 36, then subtract the lump sum.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":92853.40425970513,"tolerance":0.011}},{"id":"IBAI-1.7-P32","level":"Challenge","prompt":"A QAR 150,000 loan at 5.2% nominal annual interest is repaid monthly over 10 years. Immediately after payment 36, a QAR 20,000 lump sum reduces the balance to QAR 92,853.4042597. If the original monthly payment continues, find the approximate number of monthly payment periods remaining.","answer":"\\(66.71308\\)","solution":"Solve the annuity present-value relation for the remaining number of periods using the reduced balance and original payment. This gives about 66.713 payments, so one final smaller payment follows 66 full payments.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":66.71307999860288,"tolerance":0.011}},{"id":"IBAI-1.7-P33","level":"Challenge","prompt":"A saver deposits QAR 800 monthly for 5 years, then stops deposits but leaves the money for 4 more years at 4.8% nominal monthly. Find final value.","answer":"\\(65,560.36\\)","solution":"Accumulate the five-year annuity, then grow it for 48 additional months.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":65560.36285514002,"tolerance":0.011}},{"id":"IBAI-1.7-P34","level":"Challenge","prompt":"Compare end-of-month and beginning-of-month deposits of QAR 500 for 8 years at 5.4%. Find the advantage of beginning deposits.","answer":"\\(269.42\\)","solution":"Annuity-due value exceeds ordinary annuity by \\(FV_{ordinary}\\times i\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":269.4215545026347,"tolerance":0.011}},{"id":"IBAI-1.7-P35","level":"Challenge","prompt":"A borrower can pay QAR 2500 monthly on a QAR 180,000 loan at 4.9%. Find the number of months required.","answer":"\\(85.43274\\)","solution":"Solve \\(PV=PMT[1-(1+i)^{-n}]/i\\) for \\(n\\). This gives about 85.433 months.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":85.43273746841336,"tolerance":0.011}},{"id":"IBAI-1.7-P36","level":"Challenge","prompt":"A QAR 95,000 loan at 6% has a five-year term and QAR 500 setup fee added to principal. Find the monthly payment.","answer":"\\(1,846.28\\)","solution":"Finance QAR 95,500, not QAR 95,000.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":1846.2825460604001,"tolerance":0.011}},{"id":"IBAI-1.7-P37","level":"Challenge","prompt":"A saver increases monthly deposits by QAR 20 each year: QAR 400/month in year 1, 420/month in year 2, and so on for 5 years. At 4.2% nominal annual interest compounded monthly, find the final value.","answer":"\\(29,208.15\\)","solution":"Accumulate each year’s twelve-deposit annuity for the remaining months to the end of year 5. The total is approximately QAR 29,208.15.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":29208.1496299554,"tolerance":0.011}},{"id":"IBAI-1.7-P38","level":"Challenge","prompt":"A loan has nominal 5.8% monthly compounding. Find the effective annual rate as a percentage.","answer":"\\(5.95669\\)","solution":"Compute the twelve-period annual growth factor.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":5.956694622445657,"tolerance":0.005}},{"id":"IBAI-1.7-P39","level":"Challenge","prompt":"A QAR 70,000 loan is amortized over 6 years at 5.1%. Find the proportion of the first payment that is interest, as a percentage.","answer":"\\(26.31357\\)","solution":"Divide first-period interest by payment.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":26.31357426983969,"tolerance":0.011}},{"id":"IBAI-1.7-P40","level":"Challenge","prompt":"A QAR 70,000 loan is amortized monthly over 6 years at 5.1% nominal annual interest. Find the proportion of payment 60 that is interest, as a percentage.","answer":"\\(5.36407\\)","solution":"Find the balance after 59 payments, multiply by monthly rate for payment-60 interest, then divide by the payment. This is about 5.364%.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","financial modelling"],"check":{"mode":"number","value":5.3640655549269916,"tolerance":0.011}}],"quiz":[{"id":"IBAI-1.7-Q01","level":"Quiz","prompt":"Find monthly payment on QAR 50,000 at 4.8% over 4 years.","answer":"\\(1,146.94\\)","solution":"Use 48 payments and monthly rate.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":1146.9402782661127,"tolerance":0.011}},{"id":"IBAI-1.7-Q02","level":"Quiz","prompt":"A QAR 50,000 loan at 4.8% nominal annual interest is repaid monthly over 4 years. Find total interest.","answer":"\\(5,053.13\\)","solution":"Total paid minus principal.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":5053.133356773411,"tolerance":0.011}},{"id":"IBAI-1.7-Q03","level":"Quiz","prompt":"A QAR 50,000 loan at 4.8% nominal annual interest is repaid monthly over 4 years. Find the balance after 18 payments.","answer":"\\(32,363.00\\)","solution":"Use remaining-balance formula.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":32362.996744702574,"tolerance":0.011}},{"id":"IBAI-1.7-Q04","level":"Quiz","prompt":"Find future value of QAR 450 monthly for 5 years at 4%.","answer":"\\(29,834.54\\)","solution":"Ordinary annuity, 60 deposits.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":29834.540182186392,"tolerance":0.011}},{"id":"IBAI-1.7-Q05","level":"Quiz","prompt":"QAR 450 is deposited at the end of each month for 5 years. Find total contributions.","answer":"\\(27,000.00\\)","solution":"Multiply.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":27000,"tolerance":1e-06}},{"id":"IBAI-1.7-Q06","level":"Quiz","prompt":"QAR 450 is deposited monthly for 5 years at 4% nominal annual interest compounded monthly. The future value is QAR 29,834.540182. Find interest earned.","answer":"\\(2,834.54\\)","solution":"Future value minus contributions.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":2834.5401821863925,"tolerance":0.011}},{"id":"IBAI-1.7-Q07","level":"Quiz","prompt":"QAR 450 is deposited at the beginning of each month for 5 years at 4% nominal annual interest compounded monthly. Find the future value.","answer":"\\(29,933.99\\)","solution":"Multiply by one extra monthly factor.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":29933.98864946035,"tolerance":0.011}},{"id":"IBAI-1.7-Q08","level":"Quiz","prompt":"A QAR 100,000 loan at 5.5% over 10 years. Find monthly payment.","answer":"\\(1,085.26\\)","solution":"Use 120 payments.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":1085.2627796047984,"tolerance":0.011}},{"id":"IBAI-1.7-Q09","level":"Quiz","prompt":"A QAR 100,000 loan at 5.5% nominal annual interest is repaid monthly over 10 years. Find the interest portion of the first payment.","answer":"\\(458.33\\)","solution":"Opening balance times monthly rate.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":458.3333333333333,"tolerance":0.011}},{"id":"IBAI-1.7-Q10","level":"Quiz","prompt":"Find required monthly deposit to reach QAR 60,000 in 7 years at 4.6%.","answer":"\\(606.80\\)","solution":"Rearrange annuity formula.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":606.8031786998697,"tolerance":0.011}}],"exam":[{"id":"IBAI-1.7-E01","style":"Paper 1-style short response","title":"Vehicle loan","calculator":"Finance solver / GDC expected","total_marks":10,"context":"A QAR 85,000 loan has a nominal annual rate of 5.2%, compounded monthly, and a 6-year term.","parts":[{"label":"a","prompt":"State \\(N\\), the periodic rate, \\(PV\\) and \\(FV\\) for a finance solver.","marks":3,"answer":"\\(N=72\\), monthly rate \\(0.052/12\\), \\(PV=85000\\), \\(FV=0\\) with consistent signs.","markscheme":"A1 periods; A1 periodic rate; A1 present/future values and signs."},{"label":"b","prompt":"Find the monthly payment.","marks":2,"answer":"QAR 1,376.82","markscheme":"M1 correct finance setup; A1 payment."},{"label":"c","prompt":"Find the total interest paid.","marks":2,"answer":"QAR 14,130.96","markscheme":"M1 total payments minus principal; A1 value."},{"label":"d","prompt":"Find the outstanding balance after 24 payments.","marks":2,"answer":"QAR 59,550.98","markscheme":"M1 balance method/solver; A1 value."},{"label":"e","prompt":"Explain why the interest part of a payment decreases over time.","marks":1,"answer":"Interest is calculated on a declining outstanding balance.","markscheme":"A1 correct explanation."}]},{"id":"IBAI-1.7-E02","style":"Paper 2-style extended response","title":"University savings plan","calculator":"Finance solver / spreadsheet expected","total_marks":12,"context":"A family deposits QAR 900 at the end of each month into an account earning 4.8% nominal annual interest compounded monthly for 8 years.","parts":[{"label":"a","prompt":"Find the future value.","marks":3,"answer":"QAR 105,079.80","markscheme":"M1 periodic rate/periods; M1 annuity calculation; A1 value."},{"label":"b","prompt":"Find total contributions and interest earned.","marks":3,"answer":"Contributions QAR 86,400.00; interest QAR 18,679.80","markscheme":"A1 contributions; M1 subtraction; A1 interest."},{"label":"c","prompt":"Find the future value if deposits are made at the beginning of each month.","marks":2,"answer":"QAR 105,500.12","markscheme":"M1 annuity-due adjustment; A1 value."},{"label":"d","prompt":"The target is QAR 110,000. Find the end-of-month deposit required.","marks":3,"answer":"QAR 942.14","markscheme":"M1 rearranges annuity relation; M1 substitutes; A1 payment."},{"label":"e","prompt":"Give one limitation of assuming a constant interest rate.","marks":1,"answer":"Market rates and account terms can change.","markscheme":"A1 relevant limitation."}]}],"bankBridge":{"course":"ib-math-ai","unit":1,"lesson":"1.7","skillKeys":["IBAI.U1.SEQUENCES","IBAI.U1.MODELING"],"visibility":"authenticated-school-access","embeddedPrivatePrompts":false},"assessmentDesign":{"practiceLevels":{"Foundation":10,"Application":10,"Reasoning":10,"Challenge":10},"quizQuestions":10,"extendedTasks":2,"calculatorPolicy":"Technology is integrated throughout, with transparent setup and interpretation."}};
